            decide!(resolved_type(xt, yt, function, budget)?);
            ids!(xr, yr; xoc, yoc; xof, yof; xec, yec; xef, yef);
            Ok(Ordering::Equal)
        }
        (
            StagedCopyResultSource::TryOptionNone {
                expression: xe,
                operand: xo,
                source_instance: xs,
