        ) => {
            ids!(xe, ye; xo, yo);
            decide!(resolved_type(xs, ys, function, budget)?);
            decide!(resolved_type(xt, yt, function, budget)?);
            ids!(xp, yp; xsc, ysc; xsf, ysf; xnc, ync);
