// ----------------------------------------------------------- observation ----

fn ordinal(observation: &SkeletonObservation) -> u8 {
    match observation {
        SkeletonObservation::ReserveRenewal { .. } => 0,
        SkeletonObservation::Initialize { .. } => 1,
        SkeletonObservation::Transfer { .. } => 2,
        SkeletonObservation::CallCommit { .. } => 3,
        SkeletonObservation::Boolean { .. } => 4,
        SkeletonObservation::VariantCase { .. } => 5,
        SkeletonObservation::ArmSelected { .. } => 6,
        SkeletonObservation::Status { .. } => 7,
        SkeletonObservation::StageCopyResult(_) => 8,
        SkeletonObservation::LexicalExit { .. } => 9,
        SkeletonObservation::LoopLatch { .. } => 10,
    }
}

pub(super) fn observation(
    a: &SkeletonObservation,
    b: &SkeletonObservation,
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
) -> Result<Ordering, Diagnostic> {
    use SkeletonObservation as O;
    budget.charge(function, 1, "oracle observation kind")?;
    decide!(ordinal(a).cmp(&ordinal(b)));
    match (a, b) {
        (
            O::ReserveRenewal {
                at: xa,
                binding: xb,
            },
            O::ReserveRenewal {
                at: ya,
                binding: yb,
            },
        ) => {
            decide!(text(xa.as_str(), ya.as_str(), function, budget)?);
            place(xb, yb, function, budget)
        }
        (
            O::Initialize {
                at: xa,
                destination: xd,
            },
            O::Initialize {
                at: ya,
                destination: yd,
            },
        ) => {
            decide!(text(xa.as_str(), ya.as_str(), function, budget)?);
            place(xd, yd, function, budget)
        }
        (
            O::Transfer {
                at: xa,
                source: xs,
                destination: xd,
            },
            O::Transfer {
                at: ya,
                source: ys,
                destination: yd,
            },
        ) => {
            decide!(text(xa.as_str(), ya.as_str(), function, budget)?);
            decide!(place(xs, ys, function, budget)?);
            place(xd, yd, function, budget)
        }
        (
            O::CallCommit {
                call: xc,
                arguments: xa,
            },
            O::CallCommit {
                call: yc,
                arguments: ya,
            },
        ) => {
            decide!(text(xc.as_str(), yc.as_str(), function, budget)?);
            arguments(xa, ya, function, budget)
        }
        (
            O::Boolean {
                expression: xe,
                value: xv,
            },
            O::Boolean {
                expression: ye,
                value: yv,
            },
        ) => {
            decide!(text(xe.as_str(), ye.as_str(), function, budget)?);
            scalar(xv, yv, function, budget, "oracle boolean value")
        }
        (
            O::VariantCase {
                scrutinee: xs,
                case: xc,
                matches: xm,
            },
            O::VariantCase {
                scrutinee: ys,
                case: yc,
                matches: ym,
            },
        ) => {
            decide!(text(xs.as_str(), ys.as_str(), function, budget)?);
            decide!(text(xc.as_str(), yc.as_str(), function, budget)?);
            scalar(xm, ym, function, budget, "oracle variant match flag")
        }
        (
            O::ArmSelected {
                scrutinee: xs,
                arm: xa,
                selected: xv,
            },
            O::ArmSelected {
                scrutinee: ys,
                arm: ya,
                selected: yv,
            },
        ) => {
            decide!(text(xs.as_str(), ys.as_str(), function, budget)?);
            decide!(scalar(xa, ya, function, budget, "oracle arm ordinal")?);
            scalar(xv, yv, function, budget, "oracle arm selected flag")
        }
        (
            O::Status {
                source: xs,
                success: xv,
            },
            O::Status {
                source: ys,
                success: yv,
            },
        ) => {
            decide!(text(
                xs.expression.as_str(),
                ys.expression.as_str(),
                function,
                budget
            )?);
            decide!(scalar(
                &xs.lane,
                &ys.lane,
                function,
                budget,
                "oracle status lane"
            )?);
            scalar(xv, yv, function, budget, "oracle status success flag")
        }
        (O::StageCopyResult(x), O::StageCopyResult(y)) => compact_staged(x, y, function, budget),
        (
            O::LexicalExit {
                site: xs,
                kind: xk,
                target: xt,
            },
            O::LexicalExit {
                site: ys,
                kind: yk,
                target: yt,
            },
        ) => {
            decide!(text(xs.as_str(), ys.as_str(), function, budget)?);
            decide!(scalar(
                xk,
                yk,
                function,
                budget,
                "oracle lexical exit kind"
            )?);
            target(xt, yt, function, budget)
        }
        (O::LoopLatch { target: x }, O::LoopLatch { target: y }) => target(x, y, function, budget),
        _ => Err(mismatch(function)),
    }
}

// ------------------------------------------------------- label and path ----

pub(super) fn label(
    a: &Label,
    b: &Label,
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
) -> Result<Ordering, Diagnostic> {
    budget.charge(function, 1, "oracle label kind")?;
    match (a, b) {
        (Label::Observation(x), Label::Observation(y)) => {
            observation(x.as_ref(), y.as_ref(), function, budget)
        }
        (Label::Observation(_), Label::End(_)) => Ok(Ordering::Less),
        (Label::End(_), Label::Observation(_)) => Ok(Ordering::Greater),
        (Label::End(x), Label::End(y)) => scalar(x, y, function, budget, "oracle label terminal"),
    }
}

// This bank covers only the newly introduced comparison operation. A miss
// still executes the complete original observation comparison below.
const FLAT_IDENTITY_RECEIVERS: usize = {
    use std::mem::size_of;
    2 * size_of::<(&Rc<SkeletonObservation>, &Rc<SkeletonObservation>)>()
        + 2 * size_of::<bool>()
        + 4 * size_of::<(&mut ReplayBudget, &ResolvedFunction, usize, &str)>()
        + 4 * size_of::<Result<(), physical_budget::ByteFailure>>()
};

// The original first iterator member/work frontier is retained below. Its
// successful work payment precedes this once-only entry; no new mutable flag,
// failure owner, or caller-paid global budget field is initialized before it.
// At most one compact failure exits this invocation. Its conversion consumes
// this bank once; all unused entry/tail controls remain charged on early exit.
const FLAT_IDENTITY_ENTRY: usize = {
    use std::mem::size_of;
    type Item = Rc<SkeletonObservation>;
    type Iter = std::slice::Iter<'static, Item>;
    type Pairs = std::iter::Zip<Iter, Iter>;
    // Entry payment actual/formal arguments and complete return/receiver.
    2 * size_of::<(&mut ReplayBudget, &ResolvedFunction, usize, &str)>()
        + 2 * size_of::<Result<(), Diagnostic>>()
        // The one ByteFailure::into_diagnostic terminal conversion, plus a
        // possible preceding ByteFailure::from_budget conversion inside the
        // compact producer. Both actual/formal and return/receiving families
        // are prepaid even on a path where only the terminal conversion runs.
        // No callback/authority assumption or unused refusal text funds them.
        + 4 * size_of::<physical_budget::ByteFailure>()
        + 4 * size_of::<Diagnostic>()
        // Two tail Index receivers, results and iter() receiver pairs.
        + 12 * size_of::<&[Item]>()
        + 4 * size_of::<std::ops::RangeFrom<usize>>()
        // Two iter() return/receivers plus zip actual/formal iterator values.
        + 8 * size_of::<Iter>()
        // zip result/receiver, IntoIterator actual/formal and result/receiver.
        + 6 * size_of::<Pairs>()
};

fn items(
    a: &[Rc<SkeletonObservation>],
    b: &[Rc<SkeletonObservation>],
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
) -> Result<Ordering, Diagnostic> {
    // This is the original first zip/next/Some member binding. In particular,
    // zero work still refuses at the original member before any new byte bank.
    if let Some((x, y)) = a.iter().zip(b).next() {
        budget.charge(function, 1, "oracle flat observation member")?;
        budget.reserve_bytes(function, FLAT_IDENTITY_ENTRY, "oracle flat identity entry")?;
        physical_budget::compact_try!(budget.reserve_compact_bytes(
            function,
            FLAT_IDENTITY_RECEIVERS,
            "oracle flat identity receivers",
        ));
        physical_budget::compact_try!(budget.charge_compact(function, 1, "oracle flat observation identity"));
        if Rc::ptr_eq(x, y) {
        } else {
            decide!(observation(x.as_ref(), y.as_ref(), function, budget)?);
        }
        // Both first elements existed above. All new slices, ranges, iterator
        // returns and IntoIterator moves are now prepaid; no length is repaired.
        for (x, y) in a[1..].iter().zip(b[1..].iter()) {
            budget.charge(function, 1, "oracle flat observation member")?;
            physical_budget::compact_try!(budget.reserve_compact_bytes(
                function,
                FLAT_IDENTITY_RECEIVERS,
                "oracle flat identity receivers",
            ));
            physical_budget::compact_try!(budget.charge_compact(function, 1, "oracle flat observation identity"));
            if Rc::ptr_eq(x, y) {
                continue;
            }
            decide!(observation(x.as_ref(), y.as_ref(), function, budget)?);
        }
    }
    budget.charge(function, 1, "oracle flat observation length")?;
    Ok(a.len().cmp(&b.len()))
}

/// Exact existing prefix pointer identity, then every flat observation.
/// A pointer here identifies shared proof storage; it never grants admission.
fn observations(
    a: &Observations,
    b: &Observations,
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
) -> Result<Ordering, Diagnostic> {
    let (ap, ai) = a.parts();
    let (bp, bi) = b.parts();
    let ap = ap.map(|node| Rc::as_ptr(node) as usize);
    let bp = bp.map(|node| Rc::as_ptr(node) as usize);
    decide!(scalar(
        &ap,
        &bp,
        function,
        budget,
        "oracle observation prefix identity"
    )?);
    items(ai, bi, function, budget)
}

pub(super) fn path(
    a: &SkeletonPath,
    b: &SkeletonPath,
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
) -> Result<Ordering, Diagnostic> {
    decide!(observations(
        &a.observations,
        &b.observations,
        function,
        budget
    )?);
    scalar(
        &a.terminal,
        &b.terminal,
        function,
        budget,
        "oracle path terminal",
    )
}

/// Fallible heapsort over the already owned paths. Every probe and swap is
/// paid before execution; no standard-library sort scratch is acquired and
/// no provisional ordering can escape a refused comparison.
pub(super) fn sort(
    paths: &mut [SkeletonPath],
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
) -> Result<(), Diagnostic> {
    budget.charge(function, 1, "oracle sort header")?;
    let length = paths.len();
    for root in (0..length / 2).rev() {
        sift(paths, root, length, function, budget)?;
    }
    for end in (1..length).rev() {
        budget.charge(function, 1, "oracle sort root swap")?;
        paths.swap(0, end);
        sift(paths, 0, end, function, budget)?;
    }
    Ok(())
}
fn sift(
    paths: &mut [SkeletonPath],
    mut root: usize,
    end: usize,
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
) -> Result<(), Diagnostic> {
    loop {
        budget.charge(function, 1, "oracle sort child index")?;
        let Some(left) = root.checked_mul(2).and_then(|i| i.checked_add(1)) else {
            return Ok(());
        };
        if left >= end {
            return Ok(());
        }
        let mut child = left;
        let right = left + 1;
        budget.charge(function, 1, "oracle sort sibling probe")?;
        if right < end && path(&paths[left], &paths[right], function, budget)? == Ordering::Less {
            child = right;
        }
        budget.charge(function, 1, "oracle sort parent probe")?;
        if path(&paths[root], &paths[child], function, budget)? != Ordering::Less {
            return Ok(());
        }
        budget.charge(function, 1, "oracle sort sift swap")?;
        paths.swap(root, child);
        root = child;
    }
}

